template_changes:
.lc-method p{font-size:var(--fs-body,14px);line-height:1.55;margin:0 0 var(--sp-3,12px);max-width:85ch}
.lc-method p{font-size:var(--fs-body,14px);line-height:1.55;margin:0 0 var(--sp-3,12px);max-width:85ch}

/* Explain the existing monthly calculation without inventing example observations. */
.method-figure{margin:var(--sp-2,8px) 0 var(--sp-3,12px);max-width:560px}
.method-steps{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px 28px;list-style:none;margin:0;padding:0}
.method-steps li{position:relative;display:grid;grid-template-rows:subgrid;grid-row:span 2;min-width:0}
.method-step-label{font-size:var(--fs-sm,12.5px);line-height:1.4;color:var(--muted)}
.method-steps strong{font-size:var(--fs-body,14px);line-height:1.45;font-weight:600;color:var(--text);overflow-wrap:anywhere}
.method-steps li+li::before{content:"→";position:absolute;top:20px;left:-21px;font-size:16px;line-height:20px;color:var(--muted)}
.method-figure figcaption{font-size:var(--fs-body,14px);line-height:1.55;margin-top:10px}
.lc-method .method-distinction{margin:8px 0 0}
.lc-method[open] .method-figure{animation:method-reveal 120ms ease-out}
@keyframes method-reveal{from{opacity:.85}to{opacity:1}}

